import{_ as o,l as n,o as e,c as s,v as t,p as l,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"中断亲和","description":"","frontmatter":{"title":"中断亲和","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/irq-affinity.md","filePath":"cs/irq-affinity.md","lastUpdated":1789023840000}'),h={name:"cs/irq-affinity.md"};function A(E,a,m,_,f,u){const i=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="中断亲和" tabindex="-1">中断亲和 <a class="header-anchor" href="#中断亲和" aria-label="Permalink to &quot;中断亲和&quot;">​</a></h1><div class="epigraph"><p>把一条 IRQ 绑到指定 CPU 集合，是为了局部性与隔离，不是为了让所有核轮流当中断靶子才算公平。</p><footer>—— 据 Love, Linux Kernel Development；Tanenbaum MOS 对多处理器中断的整理</footer></div><p><a href="/cs/irq-thread">上一课</a>让处理可以是某条内核线程。线程跑在哪颗 CPU 上，还取决于这条 IRQ 被投递到哪。<a href="/cs/interconnect-numa">互连与 NUMA</a> 已经说明远端访问更贵。缺口是：<strong>中断亲和</strong>——I/O APIC / MSI 把向量送到哪些核——从而决定上半部在哪跑、缓存里热的是哪套描述符。本课只钉投递集合，不写负载均衡迁移算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若所有设备中断都打到 CPU0，该核的<a href="/cs/scheduling-metrics">调度指标</a>被 ISR 与软中断淹没，其它核再公平也救不了这条延迟。若每条 IRQ 在所有核间乱跳，网卡环形缓冲的 cache 行会来回失效。缺口不是新的下半部种类，而是把 IRQ 的 CPU 掩码当成配置对象：可以绑单核、可以绑一个 NUMA 节点。</p><p><span class="marginnote">亲和是投递策略。处理线程还可以另有 CPU 亲和；两者不一致时，上半部在 A 核，线程在 B 核，多一次跨核唤醒。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬件：MSI/MSI-X 或 I/O APIC 表项里写目标 APIC ID 或集合。内核：为每条 IRQ 保存 <code>cpumask</code>，在亲和变更时重编程硬件。隔离：实时 CPU 可以从掩码里拿掉，使那些核几乎只跑期限任务。本课不把 <code>/proc/irq</code> 的管理接口当正文。</p>',8)),(e(),l(p,null,{default:r(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEV%5B%22%E8%AE%BE%E5%A4%87%E5%90%91%E9%87%8F%22%5D%20--%3E%20MASK%5B%22IRQ%20%E4%BA%B2%E5%92%8C%E6%8E%A9%E7%A0%81%22%5D%0A%20%20MASK%20--%3E%20CPU%5B%22%E7%9B%AE%E6%A0%87%20CPU%20%E4%B8%8A%E7%A1%AC%E4%B8%AD%E6%96%AD%22%5D%0A%20%20CPU%20--%3E%20THR%5B%22%E5%90%8C%E6%A0%B8%E6%88%96%E8%B7%A8%E6%A0%B8%E7%9A%84%E5%A4%84%E7%90%86%E7%BA%BF%E7%A8%8B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与后课 CPU 亲和（线程绑核）是一对：一个管中断从哪进，一个管线程在哪跑。本课只管前者。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>正确的亲和让上半部碰到的描述符仍在该核 L1/L2，也让「时钟中断打在每核、设备中断打在指定核」成为可叙述的政策。错误的亲和制造虚假热点：看起来利用率不高，其实 CPU0 的软中断占满。这与公平调度摊时间不是同一把尺子——中断不是 CFS 实体。</p><p>平衡设备中断可以用轮转或按队列的 RSS/多队列网卡：每条队列一个 MSI-X 向量、一个掩码。主干只承认多向量，不写驱动。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把中断重均衡守护进程写成必装组件，不讨论虚拟化里 IRQ 投递到 vCPU 的全部路径。NMI 与机器检查往往不受普通亲和表约束，下一课单独处理。</p><p>后课默认：设备 IRQ 可绑核。有一类中断不能按普通掩码推迟或屏蔽，下一课讲 NMI。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>中断亲和：向量投递到哪些 CPU，影响缓存与隔离。</li><li>与线程绑核相关但不是同一对象。</li><li>不可屏蔽中断是下一课。</li><li>出处：Love, <em>LKD</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',9))])}const I=o(h,[["render",A]]);export{C as __pageData,I as default};
